import '@components/z-modal/index.less'
import './reset-modal.less'

import normalizeStyle from '@style/normalize.css?raw'
import commonStyle from './common.css?raw'
import style from './index.css?raw'

// 组件懒加载，需要在顶层引入，防止被 tree-shaking 掉
import { getSceneList, getElectricalList, queryMaxPower, getRecommendEnergy, shopifyCartAdd, getRecommendEnergySolar, getRecommendSolution, getMyOffer, } from '@utils/api.js'

import { isMobile } from '@utils/index.js'

// 共享数据
import { SharedState } from './shared-state.js'

const template = document.createElement("template")
template.innerHTML = `
  <style>
    ${normalizeStyle}
    ${commonStyle}
    ${style}
    .container {
      background-color: var(--bg-color, #F5F5F5);
      padding-top: var(--padding-top, 5.33333333333333vw);
      padding-bottom: var(--padding-bottom, 3.2vw);
      min-height: var(--min-height, 109.466666666667vw);
    }
    @media (min-width: 1024px) {
      .container {
        padding-top: var(--padding-top, 4.44444444444444vw);
        padding-bottom: var(--padding-bottom, 5vw);
        min-height: var(--min-height, 38.75vw);
      }
      .container [data-content-wrap] {
        zoom: var(--zoom-pc, 1);
      }
    }
    @media (min-width: 1440px) {
      .container {
        padding-top: var(--padding-top, 64px);
        padding-bottom: var(--padding-bottom, 72px);
        min-height: var(--min-height, 558px);
      }
      .container [data-content-wrap] {
        zoom: var(--zoom-pc, 1);
      }
    }
  </style>
  <div class="container w-full max-h-fit">
    <div class="w-full mx-auto lg:j-w-1200 xl:a-w-1200" data-content-wrap>
      <!-- 进度条 -->
      <div class="flex items-center justify-start gap-x-16 px-48 mb-32 lg:px-0 lg:j-gap-x-12 lg:j-mb-24 xl:a-gap-x-12 xl:a-mb-24">
        <div class="w-500 h-12 rounded-full bg-white border-solid border-#1A1A1A border-1 lg:j-border-1 lg:j-w-500 lg:j-h-8 xl:a-border-1 xl:a-w-500 xl:a-h-8">
          <div class="h-full bg-#1A1A1A rounded-full transition-width duration-300 w-1/5" data-progress-bar></div>
        </div>
        <span class="text-#1A1A1A font-medium text-28 leading-42 lg:j-text-14 lg:j-leading-20 xl:a-text-14 xl:a-leading-20" data-progress-step>1/5</span>
      </div>

      <!-- 标题 -->
      <h3 class="title"></h3>

      <!-- loading 插槽 -->
      <slot name="loading"></slot>
    </div>
  </div>
`

class jkySmartRecommend extends HTMLElement {
  constructor() {
    super()
    const shadow = this.attachShadow({ mode: 'open' })

    // 应用构造的样式表
    // shadow.adoptedStyleSheets = [sheet];
    shadow.appendChild(template.content.cloneNode(true))

    // loading 插槽
    this.loadingSlot = this.shadowRoot.querySelector('slot[name="loading"]')
    // content wrap
    this.contentWrap = this.shadowRoot.querySelector('[data-content-wrap]')
    
    // 添加加载状态标志
    this.isLoading = false
    // 添加步骤加载状态映射
    this.stepsLoading = {1: false, 2: false, 3: false, 4: false, 5: false}
  }
  async connectedCallback() {
    // 初始化组件属性
    this.initializeProperties()
    
    // 获取 JSON 多语言数据
    this.loadJsonData()

    // 根据 URL 参数决定显示方式
    if (getUrlQueryParams('show_result') === '1') {
      await this.showResultDirectly()
    } else {
      await this.startFromFirstStep()
    }
  }
  // 初始化组件属性
  initializeProperties() {
    // 获取组件使用类型
    this.type = this.getAttribute('type') // ['page', 'modal'] 区分页面类型 和 弹窗类型
  
    this.shopifyShopId = this.getAttribute('shopify-shop-id') || getUrlQueryParams('shopify_shop_id') || window?.pageInfo?.shopId
    this.compareId = this.getAttribute('compare-id') // 产品对比 ID
    this.couponId = this.getAttribute('coupon-id') // 优惠券 ID
  }
  // 加载 JSON 多语言数据
  loadJsonData() {
    const scriptTag = document.querySelector('script[type="application/json"][id="smart-recommend-4-json"]');
    if (scriptTag) {
      // 提取 JSON 数据并解析
      this.jsonData = JSON.parse(scriptTag.textContent)
    } else {
      this.jsonData = {}
    }
  }
  // 直接显示推荐结果
  async showResultDirectly() {
    // 隐藏进度条
    this.contentWrap.querySelector('[data-progress-step]').parentElement.classList.add('!hidden')

    // 更新标题
    this.updateTitle(5)

    // 渲染推荐结果，动态导入模块
    const module = await this.getComponentModule(5)
    if (!customElements.get('jky-smart-choose-5')) {
      customElements.define('jky-smart-choose-5', module.default)
      console.log(`加载组件 jky-smart-choose-5 完成`)
    }

    // 隐藏 loading 插槽内容
    this.hideLoadingSlot()

    // 载入组件
    const jkySmartChoose5 = document.createElement('jky-smart-choose-5')

    // 使用对象映射设置属性，减少重复代码
    const attributes = {
      'shopify-shop-id': this.shopifyShopId,
      'energy-gid': getUrlQueryParams('energy_gid'),
      'solar-gid': getUrlQueryParams('solar_gid'),
      'solar-num': getUrlQueryParams('solar_num'),
      'coupon-id': this.couponId || '', // 优惠券 ID
      'show-result-only': true, // 仅展示推荐结果
    }
    // 遍历对象设置属性
    Object.entries(attributes).forEach(([key, value]) => jkySmartChoose5.setAttribute(key, value))
    this.contentWrap.appendChild(jkySmartChoose5)
    jkySmartChoose5.init(this.jsonData)
  }
  // 从第一步开始
  async startFromFirstStep() {
    // 更新标题
    this.updateTitle(1)

    // 动态导入模块
    const module = await this.getComponentModule(1)
    if (!customElements.get('jky-smart-choose-1')) {
      customElements.define('jky-smart-choose-1', module.default)
      console.log(`加载组件 jky-smart-choose-1 完成`)
    }

    // 隐藏 loading 插槽内容
    this.hideLoadingSlot()

    // 载入组件
    const jkySmartChoose1 = document.createElement('jky-smart-choose-1')
    jkySmartChoose1.setAttribute('shopify-shop-id', this.shopifyShopId)
    this.contentWrap.appendChild(jkySmartChoose1)
    jkySmartChoose1.init(this.jsonData)
    
    // 预加载下一步组件
    this.preFetchComponent(2)
  }
  // 更新进度条
  updateProgressBar(step) {
    this.contentWrap.querySelector('[data-progress-bar]').style.width = 20 * step + '%'
    this.contentWrap.querySelector('[data-progress-step]').textContent = `${step}/5`
  }
  // 更新标题
  updateTitle(step) {
    this.contentWrap.querySelector('.title').innerHTML = this.jsonData.smart_recommend_4[`step_${step}`].title
  }
  // 预加载下一步组件
  preFetchComponent(nextStep) {
    if (nextStep > 5) return; // 最多5个步骤
    
    // 如果下一步组件未定义，则预加载
    if (!customElements.get(`jky-smart-choose-${nextStep}`)) {
      // 如果浏览器支持 requestIdleCallback，则在浏览器空闲时预加载下一个组件
      if (window.requestIdleCallback) {
        requestIdleCallback(() => this.loadComponent(nextStep), { timeout: 2000 }) // 设置超时时间为2秒
      } else {
        // 如果不支持 requestIdleCallback，则使用 setTimeout 作为替代方案
        setTimeout(() => this.loadComponent(nextStep), 0) // 立即执行
      }
    }
    // 如果下一步组件已经定义，则不需要再次加载，直接载入即可
    else {
      // 插入组件
      this.insertComponent(nextStep)
    }
  }
  // 懒加载组件
  async loadComponent(nextStep) {
    try {
      // 使用公共方法获取模块
      const loadedModule = await this.getComponentModule(nextStep)
      if (!loadedModule) return
      
      // 注册自定义元素
      if (!customElements.get(`jky-smart-choose-${nextStep}`)) {
        customElements.define(`jky-smart-choose-${nextStep}`, loadedModule.default)
        console.log(`预加载组件 jky-smart-choose-${nextStep} 完成`)
      }
      
      // 插入组件
      this.insertComponent(nextStep)
    } catch (error) {
      console.error(`预加载组件 jky-smart-choose-${nextStep} 失败:`, error)
    }
  }
  // 插入组件
  insertComponent(nextStep) {
    const fetchedComponent = document.createElement(`jky-smart-choose-${nextStep}`)

    // 使用对象映射设置属性，减少重复代码
    const attributes = {
      'shopify-shop-id': this.shopifyShopId,
      'compare-id': this.compareId || '', // 产品对比 ID
      'coupon-id': this.couponId || '', // 优惠券 ID
      'type': this.type, // ['page', 'modal'] 区分页面类型 和 弹窗类型
    }
    // 遍历对象设置属性
    Object.entries(attributes).forEach(([key, value]) => fetchedComponent.setAttribute(key, value))
    fetchedComponent.style.display = 'none'
    this.contentWrap.appendChild(fetchedComponent)
  }
  // 获取组件模块的公共方法
  async getComponentModule(step) {
    if (step < 1 || step > 5) {
      console.error('无效的步骤:', step)
      return null
    }

    let module;
    switch (step) {
      case 1:
        module = import(/* webpackChunkName: "jky-smart-choose-1" */'./snippets/jky-smart-choose-1/index.js')
        break
      case 2:
        module = import(/* webpackChunkName: "jky-smart-choose-2" */'./snippets/jky-smart-choose-2/index.js')
        break
      case 3:
        module = import(/* webpackChunkName: "jky-smart-choose-3" */'./snippets/jky-smart-choose-3/index.js')
        break
      case 4:
        module = import(/* webpackChunkName: "jky-smart-choose-4" */'./snippets/jky-smart-choose-4/index.js')
        break
      case 5:
        module = import(/* webpackChunkName: "jky-smart-choose-5" */'./snippets/jky-smart-choose-5/index.js')
        break
      default:
        return
    }
    
    return module
  }
  // 隐藏 loading 插槽内容的方法
  hideLoadingSlot() {
    if (this.loadingSlot) {
      const assignedNodes = this.loadingSlot.assignedNodes()
      assignedNodes.forEach(node => {
        if (node.style) {
          node.style.display = 'none'
        }
      })
    }
  }
  // 处理步骤操作
  async handleStepAction({ detail, }) {
    // 如果当前正在加载中，则忽略此次操作
    if (this.isLoading) {
      console.log('操作正在处理中，请稍候...')
      return
    }
    
    let { step, action, ...rest } = detail
    
    // 设置加载状态
    this.isLoading = true
  
    try {
      // 下一步
      if (action === 'next') {
        const nextStep = step + 1
        
        // 显示指定步骤，隐藏其他步骤
        this.showStepAndHideOthers(nextStep)
        
        // 检查下一步组件是否已经在加载中
        if (this.stepsLoading[nextStep]) {
          console.log(`步骤 ${nextStep} 正在加载中，请稍候...`)
          return
        }
        
        // 标记该步骤正在加载
        this.stepsLoading[nextStep] = true
        
        // 懒加载下一步，兜底逻辑
        if (!customElements.get(`jky-smart-choose-${nextStep}`)) {
          // 使用公共方法获取模块
          const module = await this.getComponentModule(nextStep)
          if (!module) {
            this.stepsLoading[nextStep] = false
            this.isLoading = false
            return
          }
        
          // 再次检查组件是否已定义（防止在模块加载过程中被其他地方定义）
          if (!customElements.get(`jky-smart-choose-${nextStep}`)) {
            customElements.define(`jky-smart-choose-${nextStep}`, module.default)
          }
      
          // 检查是否已经存在该组件实例
          const existingComponent = this.contentWrap.querySelector(`jky-smart-choose-${nextStep}`)
          if (!existingComponent) {
            // 载入组件
            const jkySmartChooseStep = document.createElement(`jky-smart-choose-${nextStep}`)
        
            // 使用对象映射设置属性，减少重复代码
            const attributes = {
              'shopify-shop-id': this.shopifyShopId,
              'compare-id': this.compareId || '', // 产品对比 ID
              'coupon-id': this.couponId || '', // 优惠券 ID
              'type': this.type, // ['page', 'modal'] 区分页面类型 和 弹窗类型
            }
            // 遍历对象设置属性
            Object.entries(attributes).forEach(([key, value]) => jkySmartChooseStep.setAttribute(key, value))
            
            // 遍历 rest 并映射属性
            Object.entries(rest).forEach(([key, value]) => jkySmartChooseStep.setAttribute(key, value))
            this.contentWrap.appendChild(jkySmartChooseStep)
            jkySmartChooseStep.init(this.jsonData)
          } else {
            // 如果已存在，只需要更新属性和显示
            Object.entries(rest).forEach(([key, value]) => existingComponent.setAttribute(key, value))
            existingComponent.style.display = 'block'
            existingComponent.init(this.jsonData)
          }
        } else {
          // 查找组件
          const jkySmartChooseStep = this.contentWrap.querySelector(`jky-smart-choose-${nextStep}`)
          if (jkySmartChooseStep) {
            // 遍历 rest 并映射属性
            Object.entries(rest).forEach(([key, value]) => jkySmartChooseStep.setAttribute(key, value))
            // 显示下一步
            jkySmartChooseStep.style.display = 'block'
            jkySmartChooseStep.init(this.jsonData)
          } else {
            // 如果找不到组件，则创建一个
            const newComponent = document.createElement(`jky-smart-choose-${nextStep}`)
            // 设置属性
            const attributes = {
              'shopify-shop-id': this.shopifyShopId,
              'compare-id': this.compareId || '',
              'coupon-id': this.couponId || '',
              'type': this.type, // ['page', 'modal'] 区分页面类型 和 弹窗类型
            }
            Object.entries(attributes).forEach(([key, value]) => newComponent.setAttribute(key, value))
            Object.entries(rest).forEach(([key, value]) => newComponent.setAttribute(key, value))
            this.contentWrap.appendChild(newComponent)
            newComponent.init(this.jsonData)
          }
        }
        
        // 更新进度条
        this.contentWrap.querySelector('[data-progress-bar]').style.width = 20 * nextStep + '%'
        this.contentWrap.querySelector('[data-progress-step]').textContent = `${nextStep}/5`

        // 更新标题
        this.contentWrap.querySelector('.title').innerHTML = this.jsonData.smart_recommend_4[`step_${nextStep}`].title
        
        // 预加载下一步组件
        this.preFetchComponent(nextStep + 1)
      }
      // 上一步
      else if (action === 'back') {
        const prevStep = step - 1
        // 显示指定步骤，隐藏其他步骤
        this.showStepAndHideOthers(prevStep)

        // 更新进度条
        this.contentWrap.querySelector('[data-progress-bar]').style.width = 20 * prevStep + '%'
        this.contentWrap.querySelector('[data-progress-step]').textContent = `${prevStep}/5`

        // 更新标题
        this.contentWrap.querySelector('.title').innerHTML = this.jsonData.smart_recommend_4[`step_${prevStep}`].title
      }
      // 再试一次
      else {
        // 显示指定步骤，隐藏其他步骤
        this.showStepAndHideOthers(1)
        // 第一步重新初始化
        this.contentWrap.querySelector(`jky-smart-choose-1`)?.init(this.jsonData)

        // 更新进度条
        this.contentWrap.querySelector('[data-progress-bar]').style.width = 20 * 1 + '%'
        this.contentWrap.querySelector('[data-progress-step]').textContent = `1/5`

        // 更新标题
        this.contentWrap.querySelector('.title').innerHTML = this.jsonData.smart_recommend_4.step_1.title

        // 清除共享数据
        SharedState.clearData()
      }
      // 滚动到组件顶部
      this.scrollToComponent()
    } catch (error) {
      console.error('处理步骤操作时出错:', error)
    } finally {
      // 重置加载状态
      this.isLoading = false
      // 重置当前步骤的加载状态
      if (action === 'next') {
        this.stepsLoading[step + 1] = false
      }
    }
  }
  // 显示指定步骤，隐藏其他步骤
  showStepAndHideOthers(targetStep) {
    // 隐藏所有步骤，只显示目标步骤
    for (let i = 1; i <= 5; i++) {
      const stepElement = this.contentWrap.querySelector(`jky-smart-choose-${i}`)
      if (stepElement) {
        stepElement.style.display = i === targetStep ? 'block' : 'none'
      }
    }
  }
  scrollToComponent() {
    const header = document.querySelector('jky-header') || document.querySelector('header-v5')
    const headerHeight = Math.ceil(header.getBoundingClientRect().height)
    const targetElement = document.querySelector('jky-smart-recommend')
    if (targetElement) {
      // 使用方式非弹窗
      if (this.type !== 'modal') {
        // getAbsoluteTop 是全局的函数，在 global.js 中定义
        const targetPosition = getAbsoluteTop(targetElement) - headerHeight
        window.scrollTo({
          top: targetPosition,
          behavior: "smooth"
        })
      } else {
        // 查找滚动的父元素
        const parentElement = isMobile ? targetElement.parentElement.parentElement : targetElement.parentElement
        parentElement.scrollTo({
          top: 0, // 滚动到容器顶部
          behavior: 'smooth'
        })
      }
    }
  }
  // 获取标题字符串
  getTitleString() {
    return this.contentWrap.querySelector('.title')?.innerText
  }
}

customElements.define('jky-smart-recommend', jkySmartRecommend)

// 支持模块化导入
export default jkySmartRecommend
